css:
body { color:#171717; background:white; font-size:10.2pt; line-height:1.43; }
* { box-sizing:border-box; }
h1,h2,h3,p,ul,table { margin:0; }
a { color:inherit; text-decoration:none; }
strong { font-weight:700; }
p { margin:4pt 0; }
ul { padding-left:13pt; margin:4pt 0 7pt; }
li { margin:2pt 0; }
h2 { font-size:12pt; line-height:1.3; margin:14pt 0 7pt; padding:0 0 4pt; border:0; border-bottom:1px solid #333; }
h3 { font-size:10.6pt; line-height:1.35; margin:9pt 0 3pt; border:0; }
table { width:100%; border-collapse:collapse; font-size:9.7pt; margin:5pt 0 10pt; }
th,td { text-align:left; vertical-align:top; padding:5pt 7pt; border:0; border-bottom:1px solid #d1d5da; background:white; }
th { background:#f0f2f4; font-weight:700; }
td ul { margin:0; padding-left:12pt; }
.resume-sheet { width:100%; }
.meta { color:#555; font-size:9.2pt; }
.project-table td:first-child { width:22%; font-weight:600; background:#f6f7f8; }
.project-table td { padding:5pt 7pt; }

body { font-family:"Times New Roman",Times,serif; font-size:10.1pt; line-height:1.17; }
h1 { text-align:center; font-size:25pt; font-weight:normal; line-height:1.05; border:0; padding:0; margin:0 0 4pt; }
.contacts { text-align:center; font-size:9pt; margin:0 0 10pt; }
.contacts a { text-decoration:underline; }
h2 { text-transform:uppercase; font-variant:small-caps; font-size:11.2pt; font-weight:normal; margin:10pt 0 4pt; padding-bottom:2pt; border-bottom:0.6pt solid black; }
h3 { font-size:10.2pt; margin:6pt 0 2pt; }
ul { margin:3pt 0 5pt; padding-left:13pt; }
li { margin:1.7pt 0; }
p { margin:2pt 0 4pt; }
.meta { color:#171717; font-size:9.5pt; }
.entry-title { display:flex; justify-content:space-between; gap:8pt; align-items:baseline; }
.entry-title span { white-space:nowrap; font-size:9.5pt; }
